/**
 * For ZOOKEEPER-1755 - Test race condition when taking dumpEphemerals and
 * removing the session related ephemerals from DataTree structure
 */
@Test(timeout = 60000)
public void testDumpEphemerals() throws Exception {
    int count = 1000;
    long session = 1000;
