    CnxnThread[] threads = new CnxnThread[numThreads];
    for (int i = 0; i < numCnxns; ++i) {
        threads[i] = new CnxnThread(i);
    }
    for (int i = 0; i < numCnxns; ++i) {
        threads[i].start();
    }
    for (int i = 0; i < numCnxns; ++i) {
